import{t as e}from"./utils-COoNfFoj.js";var t={slug:`sabreen-haziq`,influencerName:`Sabreen Haziq`,influencerHandle:`@sabreenhaziq`,influencerAvatarUrl:`${e}/sabreen-haziq-avatar.jpeg`,heroDescription:`I created this build to understand the nuances of what works in my YouTube topic niche so I can create more outlier videos.`,assetTitle:`This Week’s Bloom`,screenshotUrl:`${e}/sabreen-haziq.png`,remixUrl:`https://www.perplexity.ai/computer/a/this-week-s-bloom-z5QuoI6bShuP2rteTrIGjg`,promptTitle:`Try Sabreen's prompt`,promptText:`Build “This Week’s Bloom” as a cinematic graveyard at midnight: near-black background, smoky fog, neon green and red accents, with a semi-transparent ghost that drifts continuously across the page. The 10 outlier videos sit as gothic tombstones with hyper-realistic flowers blooming at their base, sortable by multiple, date, views, and subs, each linking out to YouTube. Alongside that, there’s a Pattern Analysis panel synthesizing the week’s insights, a clickable Niche Watch panel showing adjacent content categories, and a KPI strip up top with the key stats. The dashboard includes a “Your Creative Brief” section at the bottom that takes the week’s outlier research and drafts 3-5 video concepts for my own channel, each with a working title, hook angle, format, and a note on why the concept could work based on the week’s data. The tool moves from research → drafted creative output in one system, landing closer to the execution layer.`};export{t as default};
